INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3160, '\(\angle xOy = 50^\circ\) និង \(\angle yOz = 70^\circ\) ជាមុំជាប់គ្នា។ \(Oh\), \(Ot\) ជាកន្លះបន្ទាត់ពុះមុំនៃមុំទាំងពីរ។ \(\angle hOt\) ស្មើ៖', NULL, '["\\(60^\\circ\\)", "\\(120^\\circ\\)", "\\(50^\\circ\\)", "\\(30^\\circ\\)"]', 0, NULL, 2, 'mcq', '\(25 + 35 = 60\)។', 'មុំ', 'medium', 1, '7', 'មុំ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3161, 'បន្ទាត់ពីរប្រសព្វគ្នាត្រង់ \(O\) បង្កើត \(\angle O_1 = 70^\circ\)។ មុំទល់កំពូលនឹង \(O_1\) មានរង្វាស់៖', NULL, '["\\(110^\\circ\\)", "\\(290^\\circ\\)", "\\(70^\\circ\\)", "\\(20^\\circ\\)"]', 2, NULL, 2, 'mcq', 'មុំទល់កំពូលស្មើគ្នា។', 'មុំ', 'medium', 1, '7', 'មុំ', NULL, 0);
