INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3173, 'នាឡិកាបង្ហាញម៉ោង \(9:00\)។ ក. ទ្រនិចទាំងពីរផ្គុំជាមុំលយប៉ុន្មានដឺក្រេ? ខ. មុំផត (ម្ខាងទៀត) ប៉ុន្មានដឺក្រេ? គ. មុំណាជាមុំកែង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(9:00\) ទ្រនិចនាទីនៅ \(12\) ទ្រនិចម៉ោងនៅ \(9\) ចម្ងាយ \(3\) ម៉ោង \(= 3 \times 30 = 90^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3174, 'ជណ្តើរមួយផ្អៀងនឹងជញ្ជាំងបញ្ឈរ ហើយផ្គុំជាមួយដីដេកមុំ \(65^\circ\)។ ក. ជណ្តើរផ្គុំជាមួយជញ្ជាំងមុំប៉ុន្មាន? ខ. បើគេសង់ជណ្តើរបន្ថែមមួយទៀតផ្គុំជាមួយដីមុំ \(75^\circ\) មុំជាមួយជញ្ជាំងប៉ុន្មាន? គ. ជណ្តើរណាផ្អៀងចោតជាង?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(90 - 65 = 25^\circ\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3175, 'ទ្វារបន្ទប់បើកដំបូង \(35^\circ\) ពីជញ្ជាំង រួចបើកបន្ថែម \(25^\circ\) រួចបើកបន្ថែមទៀត \(30^\circ\)។ ក. ទ្វារផ្គុំជាមួយជញ្ជាំងប៉ុន្មាន? ខ. ជាមុំប្រភេទអ្វី? គ. ត្រូវបើកទ្វារបន្ថែមប៉ុន្មានដឺក្រេទៀត ទើបទ្វារនិងជញ្ជាំងផ្គុំជាមុំរាប?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(35 + 25 + 30 = 90^\circ\) (2 ពិន្ទុ)
